class Solution:
    def leastInterval(self, tasks: List[str], n: int) -> int:
        counts = {}
        for t in tasks:
            counts[t] = counts.get(t, 0) + 1
        max_freq = max(counts.values())
        max_count = sum(1 for v in counts.values() if v == max_freq)
        part_count = max_freq - 1
        empty_slots = part_count * (n - (max_count - 1))
        available_tasks = len(tasks) - max_freq * max_count
        idles = max(0, empty_slots - available_tasks)
        return len(tasks) + idles

class Solution {
public:
    int leastInterval(vector<char>& tasks, int n) {
        vector<int> counts(26, 0);
        for (char t : tasks) counts[t - 'A']++;
        int max_freq = 0;
        for (int c : counts) max_freq = max(max_freq, c);
        int max_count = 0;
        for (int c : counts) {
            if (c == max_freq) max_count++;
        }
        int ans = (max_freq - 1) * (n + 1) + max_count;
        return max(ans, (int)tasks.size());
    }
};

class Solution {
    public int leastInterval(char[] tasks, int n) {
        int[] counts = new int[26];
        for (char t : tasks) counts[t - 'A']++;
        int maxFreq = 0;
        for (int c : counts) maxFreq = Math.max(maxFreq, c);
        int maxCount = 0;
        for (int c : counts) {
            if (c == maxFreq) maxCount++;
        }
        int ans = (maxFreq - 1) * (n + 1) + maxCount;
        return Math.max(ans, tasks.length);
    }
}

var leastInterval = function(tasks, n) {
    const counts = new Array(26).fill(0);
    for (const t of tasks) counts[t.charCodeAt(0) - 65]++;
    let maxFreq = 0;
    for (const c of counts) maxFreq = Math.max(maxFreq, c);
    let maxCount = 0;
    for (const c of counts) {
        if (c === maxFreq) maxCount++;
    }
